create table hub (lat float(53) not null, lon float(53) not null, id bigint not null auto_increment, meeting_point varchar(255) not null, name varchar(255) not null, primary key (id)) engine=InnoDB;
create table login_token (expires_at datetime(6) not null, id bigint not null auto_increment, member_id bigint not null, token_hash varchar(255) not null, primary key (id)) engine=InnoDB;
create table mail_outbox (attempts integer not null, id bigint not null auto_increment, next_attempt_at datetime(6) not null, body varchar(2000) not null, recipient varchar(255) not null, subject varchar(255) not null, status enum ('FAILED','PENDING','SENT') not null, primary key (id)) engine=InnoDB;
create table member (login_code_failures integer not null, login_failure_day date, login_failures_today integer not null, no_show_count integer not null, id bigint not null auto_increment, login_code_expires_at datetime(6), login_code_sent_at datetime(6), school_id bigint not null, email varchar(255) not null, login_code varchar(255), nickname varchar(255), gender enum ('FEMALE','MALE'), primary key (id)) engine=InnoDB;
create table party (boarded_at datetime(6), departure_at datetime(6) not null, expected_total bigint not null, hub_id bigint, id bigint not null auto_increment, payer_id bigint not null, school_id bigint, version bigint not null, direction enum ('FROM_HUB','TO_SCHOOL') not null, status enum ('CANCELED','COMPLETED','CONFIRMED','SETTLING','UNSETTLED') not null, primary key (id)) engine=InnoDB;
create table ride_request (arrived bit not null, no_show bit not null, point_lat float(53) not null, point_lon float(53) not null, ride_order integer, shared_seconds integer not null, solo_km float(53) not null, solo_seconds integer not null, active_member_id bigint, arrive_by datetime(6), board_at datetime(6), deadline_slot datetime(6), expected_share bigint, hub_id bigint, id bigint not null auto_increment, member_id bigint not null, party_id bigint, ratio_units bigint, school_id bigint, solo_fare bigint not null, version bigint not null, window_end datetime(6), window_start datetime(6), memo varchar(255), point_name varchar(255) not null, direction enum ('FROM_HUB','TO_SCHOOL') not null, end_reason enum ('LEFT_ALONE','NO_SHOW','PARTY_CANCELED'), status enum ('CANCELED','COMPLETED','MATCHED','UNMATCHED','WAITING') not null, primary key (id)) engine=InnoDB;
create table school (lat float(53) not null, lon float(53) not null, id bigint not null auto_increment, email_domain varchar(255) not null, gate_name varchar(255) not null, name varchar(255) not null, primary key (id)) engine=InnoDB;
create table school_hub (hub_id bigint not null, school_id bigint not null, primary key (hub_id, school_id)) engine=InnoDB;
create table settlement (revision integer not null, id bigint not null auto_increment, paid_amount bigint not null, party_id bigint not null, requested_at datetime(6) not null, stored_at datetime(6) not null, account_number varchar(255), bank_name varchar(255), receipt_content_type varchar(255), receipt_path varchar(255), primary key (id)) engine=InnoDB;
create table transfer_request (amount bigint not null, id bigint not null auto_increment, sender_id bigint not null, settlement_id bigint not null, status enum ('RECEIVED','REQUESTED','SENT') not null, primary key (id)) engine=InnoDB;
alter table login_token add constraint UK2k83awj5qybpojn7ihal1xfcf unique (token_hash);
create index idx_mail_outbox_due on mail_outbox (status, next_attempt_at);
alter table member add constraint UKmbmcqelty0fbrvxp1q58dn57t unique (email);
create index idx_ride_request_member on ride_request (member_id, id);
create index idx_ride_request_status on ride_request (status, direction);
alter table ride_request add constraint UK37cx1wmk6b36en4ff24i4q8vr unique (active_member_id);
alter table school add constraint UK54o53vsf5kqqcfumltua8vlt2 unique (email_domain);
